// ─── File: OrderSagaDemo.java ───
// Orchestrated Saga: reserve → charge → confirm, with compensations + idempotency.
// Each class below would be its own file in a real project.
package com.bank.order;

import java.math.BigDecimal;
import java.util.logging.*;

public class OrderSagaDemo {

    private static final Logger log = Logger.getLogger("Order");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OrderService orders = new OrderService();
        InventoryService inventory = new InventoryService(5);          // 5 units in stock
        PaymentService payments = new PaymentService();
        OrderSaga saga = new OrderSaga(orders, inventory, payments);

        // Rajesh has enough money → full success
        saga.placeOrder("idem-RAJ-1", "SAV2001", "ITEM-9", 2, new BigDecimal("40000"));

        // Duplicate retry with the SAME idempotency key → ignored, no double order/charge
        saga.placeOrder("idem-RAJ-1", "SAV2001", "ITEM-9", 2, new BigDecimal("40000"));

        // Priya orders but payment fails → inventory reservation is COMPENSATED (released)
        saga.placeOrder("idem-PRI-1", "CUR3001", "ITEM-9", 1, new BigDecimal("9999999"));
    }
}

// ─── orchestrator/OrderSaga.java ───  the explicit control + compensation
class OrderSaga {
    private static final Logger log = Logger.getLogger("Order");
    private final OrderService orders;
    private final InventoryService inventory;
    private final PaymentService payments;

    OrderSaga(OrderService o, InventoryService i, PaymentService p) {
        orders = o; inventory = i; payments = p;
    }

    void placeOrder(String idemKey, String account, String item, int qty, BigDecimal amount) {
        // STEP 0 — idempotent order creation (local txn in order service)
        String orderId = orders.createIfAbsent(idemKey, account, item, qty, amount);
        if (orderId == null) { log.warning(() -> "duplicate order " + idemKey + " ignored"); return; }

        boolean reserved = false;
        try {
            // STEP 1 — reserve inventory (local txn in inventory service)
            inventory.reserve(orderId, item, qty);
            reserved = true;

            // STEP 2 — charge payment (local txn in payment service, idempotent by orderId)
            payments.charge(orderId, account, amount);

            // STEP 3 — confirm order
            orders.confirm(orderId);
            log.info(() -> "ORDER " + orderId + " CONFIRMED");
        } catch (RuntimeException failure) {
            log.severe(() -> "ORDER " + orderId + " FAILED: " + failure.getMessage() + " → compensating");
            // COMPENSATION in reverse order of completed steps
            if (reserved) inventory.release(orderId, item, qty);      // semantic undo of step 1
            orders.markFailed(orderId);
        }
    }
}

// ─── inventory/InventoryService.java ───
class InventoryService {
    private static final Logger log = Logger.getLogger("Order");
    private int available;
    InventoryService(int available) { this.available = available; }

    synchronized void reserve(String orderId, String item, int qty) {   // local ACID txn
        if (available < qty) throw new IllegalStateException("out of stock");
        available -= qty;
        log.info(() -> "reserved " + qty + " of " + item + " for " + orderId + ", left=" + available);
    }
    synchronized void release(String orderId, String item, int qty) {   // compensation (idempotent)
        available += qty;
        log.warning(() -> "COMPENSATE: released " + qty + " of " + item + " for " + orderId + ", left=" + available);
    }
}

// ─── payment/PaymentService.java ───
class PaymentService {
    private static final Logger log = Logger.getLogger("Order");
    private final java.util.Map<String, BigDecimal> balances = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Set<String> charged = java.util.concurrent.ConcurrentHashMap.newKeySet();

    PaymentService() {
        balances.put("SAV2001", new BigDecimal("1000000"));   // Rajesh
        balances.put("CUR3001", new BigDecimal("250000"));    // Priya
    }

    void charge(String orderId, String account, BigDecimal amount) {    // idempotent by orderId
        if (!charged.add(orderId)) { log.warning(() -> "charge " + orderId + " already done"); return; }
        BigDecimal bal = balances.get(account);
        if (bal.compareTo(amount) < 0) {
            charged.remove(orderId);                                     // allow compensation cleanly
            throw new IllegalStateException("insufficient funds");
        }
        balances.put(account, bal.subtract(amount));                    // local ACID txn
        log.info(() -> "charged " + account + " Rs." + amount + " for " + orderId);
    }
    void refund(String orderId, String account, BigDecimal amount) {    // compensation
        balances.merge(account, amount, BigDecimal::add);
        charged.remove(orderId);
        log.warning(() -> "COMPENSATE: refunded " + account + " Rs." + amount + " for " + orderId);
    }
}

// ─── order/OrderService.java ───  idempotent creation + lifecycle
class OrderService {
    private static final Logger log = Logger.getLogger("Order");
    private final java.util.Map<String, String> byKey = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<String, String> status = new java.util.concurrent.ConcurrentHashMap<>();
    private int seq = 0;

    synchronized String createIfAbsent(String idemKey, String acc, String item, int qty, BigDecimal amt) {
        if (byKey.containsKey(idemKey)) return null;        // duplicate → caller skips
        String orderId = "ORD-" + (++seq);
        byKey.put(idemKey, orderId);
        status.put(orderId, "CREATED");
        log.info(() -> "created " + orderId + " for " + acc + " (" + qty + "×" + item + ")");
        return orderId;
    }
    void confirm(String orderId) { status.put(orderId, "CONFIRMED"); }
    void markFailed(String orderId) { status.put(orderId, "FAILED");
        log.warning(() -> orderId + " marked FAILED"); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
